&lt;p&gt;&lt;strong&gt;**Applicants must be U.S. Citizens or U.S. Permanent Residents (Green Card holders) to meet customer and regulatory requirements**&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Who We Are&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are pioneering modular motion technologies to power the next generation of innovation for Industrial, Aerospace and Defense. If&amp;nbsp;you&#39;re&amp;nbsp;excited about disrupting legacy industries, and passionate about motor control technology,&amp;nbsp;let&#39;s&amp;nbsp;chat!&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are at the forefront of innovation, crafting exclusive motion control components that propel the industrial, aerospace, and defense sectors into the future.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A couple other things:&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are open to&amp;nbsp;relocating&amp;nbsp;you&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;We have great benefits&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;We are well funded, and already generating revenue&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;We are located in beautiful Torrance, CA and just moved into a new large hangar facility&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What You&#39;ll Do&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are&amp;nbsp;seeking&amp;nbsp;a technically authoritative Responsible Engineer (RE) to serve as the single accountable engineering voice for our precision motion control products. You will own the technical integrity of assigned hardware from design release through certification and fielding — signing off on drawings, approving deviations, and standing behind every engineering decision with your name on it.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Technical Authority:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Serve as the designated Responsible Engineer for assigned products and assemblies — the final engineering signatory on drawings, specifications, test plans, and certification documentation.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design Ownership:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Own the technical baseline of assigned hardware; approve design changes, assess their impact across form, fit, and function, and&amp;nbsp;maintain&amp;nbsp;the integrity of the configuration throughout the product lifecycle.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Drawing &amp;amp; Documentation Approval:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Review and approve engineering drawings, BOMs, and specifications to ASME Y14.5 GD&amp;amp;T standards; ensure all released documentation accurately reflects the&amp;nbsp;as-designed&amp;nbsp;and as-built configuration.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deviation &amp;amp; Waiver Authority:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Evaluate and disposition non-conformances, deviations, and waivers with technical rigor; accept, reject, or impose conditions on hardware that does not meet the design baseline.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Qualification Oversight:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Provide technical oversight and approval authority for qualification and acceptance test plans and reports to DO-160 and MIL-STD-810 standards; ensure test results substantiate all performance and environmental requirements.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Certification Support:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Interface with certification authorities (FAA, DCSA, customer DERs) as the accountable engineering representative; prepare and defend technical data packages and compliance rationale.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Change Control:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Lead engineering change boards (ECBs) for assigned products; assess the technical merit, risk, and downstream impact of all proposed changes before approval.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Cross-Functional Guidance:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Provide&amp;nbsp;authoritative technical guidance to design, manufacturing, quality, and supply chain teams — resolving engineering disputes and setting the standard for what is and is not acceptable.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;22&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Communicate to the Business:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Work with the&amp;nbsp;Technical Program Manager to&amp;nbsp;create the&amp;nbsp;appropriate swim&amp;nbsp;lanes to achieve&amp;nbsp;appropriate milestones.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What You Need&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Education:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Bachelor&#39;s degree in Mechanical Engineering, Aerospace Engineering, Systems Engineering, or a related technical discipline. Master&#39;s degree or professional engineering (PE) license preferred.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;8+ years of engineering experience in aerospace, defense, or high-reliability industrial hardware, with a demonstrated&amp;nbsp;track record&amp;nbsp;of serving in a technical authority or lead engineer capacity.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Technical Depth:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Expert-level understanding of electromechanical product design including electromagnetic actuators, precision mechanisms, and avionics enclosures — sufficient to independently evaluate and approve all engineering work on assigned products.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;GD&amp;amp;T &amp;amp; Drawing Authority:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Mastery of ASME Y14.5 GD&amp;amp;T; proven ability to author, review, and approve complex 2D engineering drawings and assembly specifications.&lt;/span&gt; &lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;23&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Certification &amp;amp; Qualification:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Deep experience with aerospace or defense hardware qualification and certification processes, including DO-160, MIL-STD-810, and interaction with regulatory bodies or customer technical representatives.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What we have to offer:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are not just building components. We are reshaping the future of the Aerospace and Defense component industry, which is a $300B+ market! Come join us and help build next generation systems that will make a massive impact at global scale.&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;We offer competitive compensation: $120,000 to $140,000 base salary + equity&lt;/li&gt;
&lt;li&gt;Exceptional healthcare benefits, Medical is 100% covered by the company&lt;/li&gt;
&lt;li&gt;Flexible PTO&amp;nbsp;&lt;/li&gt;
&lt;li&gt;401K&lt;/li&gt;
&lt;li&gt;More to come!&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;

hunterpointcapital-mission-healthcare:gr.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Mission Healthcare,&amp;nbsp;located in seven states, is the largest home health and hospice company in the western United States. We have a critical mission—to take care of our people. We provide a comprehensive array of services that meet the needs of patients and families across the healthcare continuum. We believe our people, partners, patients and their families deserve care delivered with&amp;nbsp;&lt;strong&gt;C&lt;/strong&gt;ompassion,&amp;nbsp;&lt;strong&gt;A&lt;/strong&gt;ccountability,&amp;nbsp;&lt;strong&gt;R&lt;/strong&gt;espect,&amp;nbsp;&lt;strong&gt;E&lt;/strong&gt;xcellence and&amp;nbsp;&lt;strong&gt;S&lt;/strong&gt;ervice&amp;nbsp;&lt;strong&gt;(CARES),&amp;nbsp;&lt;/strong&gt;Mission Healthcare’s core values. By joining our team, you will have the opportunity to impact patient’s lives daily and grow your career in a culture of collaboration, compassion, and commitment. We are excited to continue to grow our mission family!&lt;br&gt;&lt;br&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;Mission Healthcare offers competitive benefit packages designed to support the well‑being of our team.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;strong&gt;Benefits Available to All Benefit-Eligible Employees&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;401(k) retirement savings plan&lt;/li&gt;
&lt;li&gt;Mileage reimbursement&lt;/li&gt;
&lt;li&gt;Employee Assistance Program (EAP)&lt;/li&gt;
&lt;li&gt;Paid vacation, sick leave, and holidays&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Additional Benefits for Employees Regularly Scheduled 30+ Hours per Week:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Medical, dental, and vision insurance&lt;/li&gt;
&lt;li&gt;Flexible Spending &amp;amp; Health Savings Accounts&lt;/li&gt;
&lt;li&gt;Disability, life, and AD&amp;amp;D insurance&lt;/li&gt;
&lt;li&gt;Pet insurance&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;div&gt;&lt;strong&gt;Pay range (depending on experience): $23.00 - $27.00&amp;nbsp;&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Schedule/Shift&lt;/strong&gt;: Monday-Friday, 8:00am - 5:00pm&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Territory/Location:&lt;/strong&gt; North Coastal San Diego, CA&lt;br&gt;&lt;br&gt;&lt;/div&gt;
&lt;div&gt;
&lt;div&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Providing personal care including: baths, back rubs, oral hygiene, shampoos, changing bed linen&lt;/li&gt;
&lt;li&gt;Assisting patients with dressing and undressing&lt;/li&gt;
&lt;li&gt;Skin care to prevent breakdown&lt;/li&gt;
&lt;li&gt;Assisting the patient with toileting activities&lt;/li&gt;
&lt;li&gt;Keeping patient’s living area clean and orderly, as appropriate&lt;/li&gt;
&lt;li&gt;Assisting patient in the self-administration of medication.&lt;/li&gt;
&lt;li&gt;Adhering to the Organization&#39;s documentation and care procedures and standards of personal and professional conduct.&lt;/li&gt;
&lt;li&gt;Must meet position productivity expectations as determined based on business need.&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;&lt;strong&gt;Qualifications:&lt;/strong&gt;&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Valid state Home Health Aide &amp;amp; Nursing Assistant Certifications (CHHA &amp;amp; CNA).&lt;/li&gt;
&lt;li&gt;Self-directing with the ability to work with little direct supervision.&lt;/li&gt;
&lt;li&gt;Empathy for the needs of the ill, injured, frail and the impaired.&lt;/li&gt;
&lt;li&gt;Current BLS &amp;amp; CPR certification.&lt;/li&gt;
&lt;li&gt;Demonstrates tact, patience and good personal hygiene.&lt;/li&gt;
&lt;li&gt;Valid Drivers License and Auto Insurance.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;
&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;See what Mission has to offer! &lt;a href=&quot;https://drive.google.com/file/d/1SbsmcGH6O08rEoobpgFGPE7pc_P-1MyS/view?usp=sharing&quot;&gt;Click Here.&lt;/a&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;At Mission Healthcare, we believe in fostering an inclusive workplace where diversity is valued and every employee feels respected, accepted, and empowered. We are committed to building a diverse team and creating an environment that promotes equity and belonging.&lt;/div&gt;
&lt;div&gt;
&lt;p&gt;&lt;strong&gt;Equal Opportunity &amp;amp; Veteran‑Friendly Employer:&lt;br&gt;&lt;/strong&gt;We are proud to be an equal‑opportunity employer committed to building inclusive, compassionate healthcare teams. We do not discriminate based on race, color, religion, national origin, sex, sexual orientation, gender identity, age, disability, veteran status, or any other legally protected characteristic. All employment decisions are based on qualifications, merit, and business need.&lt;/p&gt;
&lt;p&gt;Veterans and military spouses are encouraged to apply. As a &lt;strong&gt;veteran‑friendly employer&lt;/strong&gt; and proud participant in the &lt;strong&gt;We Honor Veterans Association&lt;/strong&gt;, we recognize and value the leadership, teamwork, adaptability, and service‑driven experience military‑connected individuals bring to patient‑centered care and healthcare environments.&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Accessibility Commitment:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We strive to make our hiring process accessible to all. If you require accommodations at any stage of the employment process due to a disability, please do not hesitate to let us know how we can best meet your needs.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Inclusion Efforts:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We continually work to enhance our practices by actively combating discrimination and advancing fairness and inclusivity. We encourage applicants from historically underrepresented groups to apply and join us in our mission to diversify our team and foster an environment where diverse perspectives are embraced, and every employee is given the opportunity to thrive.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Your Voice Matters:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;Mission Healthcare values your voice. We believe in maintaining a dialogue about diversity and inclusion within our teams and welcome your perspectives and innovative ideas. Together, we aim to build a workplace that reflects the communities we serve and a culture where everyone belongs.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Communication Consent:&lt;/strong&gt;&lt;br&gt;&lt;span data-teams=&quot;true&quot;&gt;By submitting an application, you acknowledge and consent to receive communications—including emails, phone calls, and text messages—from Mission Healthcare and its recruiters regarding your application and potential employment opportunities. You may opt out of text messages at any time by responding with &quot;STOP&quot;.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Let Better Growth Come To You!&lt;/strong&gt;&amp;nbsp;&lt;/div&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Mission Healthcare,&amp;nbsp;located in seven states, is the largest home health and hospice company in the western United States. We have a critical mission—to take care of our people. We provide a comprehensive array of services that meet the needs of patients and families across the healthcare continuum. We believe our people, partners, patients and their families deserve care delivered with&amp;nbsp;&lt;strong&gt;C&lt;/strong&gt;ompassion,&amp;nbsp;&lt;strong&gt;A&lt;/strong&gt;ccountability,&amp;nbsp;&lt;strong&gt;R&lt;/strong&gt;espect,&amp;nbsp;&lt;strong&gt;E&lt;/strong&gt;xcellence and&amp;nbsp;&lt;strong&gt;S&lt;/strong&gt;ervice&amp;nbsp;&lt;strong&gt;(CARES),&amp;nbsp;&lt;/strong&gt;Mission Healthcare’s core values. By joining our team, you will have the opportunity to impact patient’s lives daily and grow your career in a culture of collaboration, compassion, and commitment. We are excited to continue to grow our mission family!&lt;br&gt;&lt;br&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;Mission Healthcare offers competitive benefit packages designed to support the well‑being of our team.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;strong&gt;Benefits Available to All Benefit-Eligible Employees&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;401(k) retirement savings plan&lt;/li&gt;
&lt;li&gt;Mileage reimbursement&lt;/li&gt;
&lt;li&gt;Employee Assistance Program (EAP)&lt;/li&gt;
&lt;li&gt;Paid vacation, sick leave, and holidays&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Additional Benefits for Employees Regularly Scheduled 30+ Hours per Week:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Medical, dental, and vision insurance&lt;/li&gt;
&lt;li&gt;Flexible Spending &amp;amp; Health Savings Accounts&lt;/li&gt;
&lt;li&gt;Disability, life, and AD&amp;amp;D insurance&lt;/li&gt;
&lt;li&gt;Pet insurance&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Pay range: $95k-$115k&lt;/strong&gt;,depending on experience&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Schedule/Shift&lt;/strong&gt;: Mon-Fri 8am-5pm&lt;/div&gt;
&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/span&gt;&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;Financial Planning, Forecasting &amp;amp; Support&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Corporate Function Partnership:&lt;/strong&gt; Partner with cross-functional corporate leaders (e.g., HR, IT, Marketing, G&amp;amp;A) to provide strategic financial guidance, manage OPEX budgets, and support departmental initiatives.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Budgeting &amp;amp; Forecasting:&lt;/strong&gt; Develop, maintain, and own robust financial models to drive the annual budgeting, monthly forecasting, and long-range planning processes for corporate functions.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Scenario Modeling:&lt;/strong&gt; Run ad-hoc scenario and sensitivity analyses to evaluate the financial impact of strategic business changes, corporate restructuring, or proposed operational plans.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Headcount &amp;amp; Expense Management:&lt;/strong&gt; Oversee the financial tracking, forecasting, and optimization of corporate personnel expenses, headcount planning, and departmental spend in alignment with payroll and HR.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Reporting &amp;amp; Business Intelligence&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Variance &amp;amp; Trend Analysis:&lt;/strong&gt; Lead the development, analysis, and presentation of monthly performance trends and variance reports (Actuals vs. Budget/Forecast) for corporate functions and senior leadership.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Executive Visibility:&lt;/strong&gt; Deliver accurate, timely, and actionable financial and operational KPIs to senior leadership to drive strategic decision-making.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Dashboards &amp;amp; Visualizations:&lt;/strong&gt; Design and maintain dynamic dashboards and reports using BI tools (e.g., Power BI, Tableau, Excel) to effectively communicate corporate financial health.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Data Governance &amp;amp; Process Improvement&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Data Integrity &amp;amp; Reconciliation:&lt;/strong&gt; Lead efforts to reconcile financial system discrepancies through detailed analysis, driving collaboration with data owners to ensure data quality and consistency.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Process Optimization:&lt;/strong&gt; Identify, define, and implement continuous process improvements and automation within FP&amp;amp;A workflows to enhance operational efficiency.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Standard Operating Procedures:&lt;/strong&gt; Develop and maintain standard operating procedures (SOPs) for corporate reporting processes to ensure scalability and business continuity.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Data Security:&lt;/strong&gt; Uphold strict confidentiality and safeguard sensitive corporate financial, organizational, and personnel data.&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;Qualifications:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bachelor’s degree in&amp;nbsp;Finance,&amp;nbsp;Economics,&amp;nbsp;Business&amp;nbsp;Administration&amp;nbsp;or&amp;nbsp;a&amp;nbsp;related&amp;nbsp;field.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;5+&amp;nbsp;years&amp;nbsp;of&amp;nbsp;experience&amp;nbsp;in&amp;nbsp;financial analysis,&amp;nbsp;forecasting, budgeting,&amp;nbsp;or a related analytical role.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong analytical skills with the ability to collect, organize, analyze, and&amp;nbsp;disseminate&amp;nbsp;significant amounts of information with attention to detail and accuracy.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to handle confidential matters and information with the highest level of discretion.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prioritize daily issues,&amp;nbsp;tasks&amp;nbsp;and projects in a fast-paced environment, while&amp;nbsp;maintaining&amp;nbsp;a high standard of quality.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Comfortable working independently; self-starter with a strong work ethic.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;See what Mission has to offer! &lt;a href=&quot;https://drive.google.com/file/d/1SbsmcGH6O08rEoobpgFGPE7pc_P-1MyS/view?usp=sharing&quot;&gt;Click Here.&lt;/a&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;At Mission Healthcare, we believe in fostering an inclusive workplace where diversity is valued and every employee feels respected, accepted, and empowered. We are committed to building a diverse team and creating an environment that promotes equity and belonging.&lt;/div&gt;
&lt;div&gt;
&lt;p&gt;&lt;strong&gt;Equal Opportunity &amp;amp; Veteran‑Friendly Employer:&lt;br&gt;&lt;/strong&gt;We are proud to be an equal‑opportunity employer committed to building inclusive, compassionate healthcare teams. We do not discriminate based on race, color, religion, national origin, sex, sexual orientation, gender identity, age, disability, veteran status, or any other legally protected characteristic. All employment decisions are based on qualifications, merit, and business need.&lt;/p&gt;
&lt;p&gt;Veterans and military spouses are encouraged to apply. As a &lt;strong&gt;veteran‑friendly employer&lt;/strong&gt; and proud participant in the &lt;strong&gt;We Honor Veterans Association&lt;/strong&gt;, we recognize and value the leadership, teamwork, adaptability, and service‑driven experience military‑connected individuals bring to patient‑centered care and healthcare environments.&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Accessibility Commitment:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We strive to make our hiring process accessible to all. If you require accommodations at any stage of the employment process due to a disability, please do not hesitate to let us know how we can best meet your needs.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Inclusion Efforts:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;We continually work to enhance our practices by actively combating discrimination and advancing fairness and inclusivity. We encourage applicants from historically underrepresented groups to apply and join us in our mission to diversify our team and foster an environment where diverse perspectives are embraced, and every employee is given the opportunity to thrive.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Your Voice Matters:&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;Mission Healthcare values your voice. We believe in maintaining a dialogue about diversity and inclusion within our teams and welcome your perspectives and innovative ideas. Together, we aim to build a workplace that reflects the communities we serve and a culture where everyone belongs.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Communication Consent:&lt;/strong&gt;&lt;br&gt;&lt;span data-teams=&quot;true&quot;&gt;By submitting an application, you acknowledge and consent to receive communications—including emails, phone calls, and text messages—from Mission Healthcare and its recruiters regarding your application and potential employment opportunities. You may opt out of text messages at any time by responding with &quot;STOP&quot;.&lt;/span&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Let Better Growth Come To You!&lt;/strong&gt;&amp;nbsp;&lt;/div&gt;&lt;/div&gt;

integritypowersearch-path-robotics:green.descriptionHtml:
&lt;h1&gt;&lt;span style=&quot;font-size: 18pt;&quot;&gt;Build the Path Forward&lt;/span&gt;&lt;/h1&gt;
&lt;p&gt;At Path Robotics, we’re building the future of embodied intelligence. Our AI-driven systems enable robots to adapt, learn, and perform in the real world closing the skilled labor gap and transforming industries. We go beyond traditional methods, combining perception, reasoning, and control to deliver field-ready AI that is risk-aware, reliable, and continuously improving through real-world use.&lt;/p&gt;
&lt;p&gt;Big, hard problems are our everyday work, and our team of intelligent, humble, and driven people make the impossible possible together.&lt;/p&gt;
&lt;p&gt;We&#39;re seeking a passionate individual to join our team at the intersection of welding science and artificial intelligence. As a Staff Machine Learning Engineer, you&#39;ll be instrumental in developing robotic welding solutions. You&#39;ll use your skills in computer vision, deep learning, and Python programming to tackle challenges in our field alongside our talented teams.&lt;/p&gt;
&lt;h2&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;What You’ll Do&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Lead the development and implementation of advanced algorithms for robotic perception systems tailored to industrial welding tasks, integrating data from diverse vision sensors such as RGB/GigE, LiDAR, and ToF depth sensors.&lt;/li&gt;
&lt;li&gt;Oversee research initiatives to address complex welding-related challenges, utilizing image processing, point cloud data, and 3D sensor fusion, contributing to innovative solutions for domain-specific problems.&lt;/li&gt;
&lt;li&gt;Collaborate with multidisciplinary teams to design and lead experiments evaluating state-of-the-art deep learning models, optimizing machine learning systems for robotic perception in welding.&lt;/li&gt;
&lt;li&gt;Stay at the forefront of advancements in Robotics, Computer Vision, and ML research, driving the integration of cutting-edge technologies into real-world applications, and ensuring these innovations have a high impact on production systems.&lt;/li&gt;
&lt;li&gt;Mentor and guide junior engineers, providing technical leadership and fostering collaboration to enhance team expertise in perception systems and machine learning.&lt;/li&gt;
&lt;li&gt;Contribute to strategic decisions about system architecture and the direction of robotics perception technologies within the company, ensuring alignment with product and business goals.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Who You Are&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Master’s or Ph.D. in Computer Science, Robotics, or a related field with a focus on Computer Vision, Machine Learning, or Perception Systems.&lt;/li&gt;
&lt;li&gt;5+ years of experience in developing machine learning algorithms or applications for real-world robotics systems, particularly in industrial or manufacturing environments.&lt;/li&gt;
&lt;li&gt;Strong proficiency in Python, as well as experience with other relevant languages (e.g., C++), and a deep understanding of neural networks, deep learning architectures, and 3D data processing.&lt;/li&gt;
&lt;li&gt;Extensive experience with vision sensors (e.g., RGB, LiDAR, ToF) and demonstrated ability to apply sensor fusion techniques for perception tasks.&lt;/li&gt;
&lt;li&gt;A proven track record of leading projects and research initiatives, with the ability to bridge the gap between theoretical research and practical, deployable solutions.&lt;/li&gt;
&lt;li&gt;Enthusiastic about working in a fast-paced, dynamic startup environment, with the ability to influence company-wide technological direction and strategy.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Why You’ll Love Working Here&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Daily free lunch to keep you fueled and connected with the team&lt;/li&gt;
&lt;li&gt;Flexible PTO so you can take the time you need, when you need it&lt;/li&gt;
&lt;li&gt;Comprehensive medical, dental, and vision coverage&lt;/li&gt;
&lt;li&gt;6 weeks fully paid parental leave, plus an additional 6–8 weeks for birthing parents (12–14 weeks total)&lt;/li&gt;
&lt;li&gt;401(k) retirement plan through Empower&lt;/li&gt;
&lt;li&gt;Generous employee referral bonuses—help us grow our team!&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;div&gt;At Path Robotics we love coming to work to solve interesting and tough challenges but also because our ideas are welcomed and valued. We encourage unique thinking and are dedicated to creating a diverse and inclusive environment. All qualified applicants will receive consideration for employment without regard to race, color, religion, gender, gender identity or expression, sexual orientation, national origin, genetics, disability, age, or veteran status.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;If you require a reasonable accommodation to participate in the application process or any part of the hiring process, please contact &lt;a href=&quot;mailto:HR@path-robotics.co&quot; target=&quot;_blank&quot;&gt;HR@path-robotics.co&lt;/a&gt;m. We are committed to providing equal access and will work with qualified individuals to ensure a fair and accessible hiring experience. We will respond to your request within 48 hours.&lt;/div&gt;

investedinthemission-axon:greenhouse:763.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h4&gt;&lt;strong&gt;Join Axon and be a Force for Good.&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;At Axon, we’re on a mission to Protect Life. We’re explorers, pursuing society’s most critical safety and justice issues with our ecosystem of devices and cloud software. Like our products, we work better together. We connect with candor and care, seeking out diverse perspectives from our customers, communities and each other.&lt;br&gt;&lt;br&gt;Life at Axon is fast-paced, challenging and meaningful. Here, you’ll take ownership and drive real change. Constantly grow as you work hard for a mission that matters at a company where you matter.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Your Impact&lt;/strong&gt;&lt;br&gt;Axon Account Executives are responsible for selling Axon products and services to large and complex Law Enforcement and Public Safety agencies. This is a quota carrying, external field position. Ability to articulate complex solutions, build and maintain senior level relationships, navigate across customer agencies / units, and lead the Axon team to success is required. The position provides technical and administrative product information, demonstrations, and/or product training. You will take charge of a significant proportion of customers in Italy and engage in significant complex sales opportunities, often of 7- and 8-digit value. Your success will be built on exceptional relationship building at both operational and board-equivalent levels both externally and internally.&lt;br&gt;&lt;br&gt;At Axon, our goal is to make each individual feel valued for his or her contributions to the company’s mission to protect life. We are looking for intelligent people who want to do remarkable things. We strive to create an environment where people can succeed and enjoy coming to work every day. Life at Axon is fast paced, challenging and meaningful. Here, you’ll take ownership and drive real change. You will constantly grow as you work hard for a mission that matters at a company where you matter.&lt;br&gt;&lt;br&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Manage and grow revenue and market share at designated agencies to maximize customer satisfaction and achieve Axon’s strategic objectives&lt;/li&gt;
&lt;li&gt;Develop and maintain client relationships to ultimately drive revenue growth&lt;/li&gt;
&lt;li&gt;Develop and execute account strategy by collaborating with account team to deliver stronger, more relevant value propositions&lt;/li&gt;
&lt;li&gt;Cultivate customer relationships and ensure effective service delivery to accounts&lt;/li&gt;
&lt;li&gt;Focus on customer&#39;s satisfaction, know the customer&#39;s business and workflows, develop proper contact network within accounts&lt;/li&gt;
&lt;li&gt;Support execution of strategy at the account level&lt;/li&gt;
&lt;li&gt;Work with and bring in experts/specialists where required&lt;/li&gt;
&lt;li&gt;Oversee all account activities&lt;/li&gt;
&lt;li&gt;Responsible for forecasting, keep management in touch with accounts in a timely fashion, gather intelligence on competitor activity, and give feedback to marketing&lt;/li&gt;
&lt;li&gt;Track customer activity in internal systems in order to execute on account strategy and identify additional opportunities&lt;/li&gt;
&lt;li&gt;May provide customer product training as necessary&lt;/li&gt;
&lt;li&gt;Accountable for individual expense budget management&lt;/li&gt;
&lt;li&gt;Own account relationship and drive overall customer satisfaction for assigned accounts&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;br&gt;What You Bring&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Professional background:&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;5+ years customer facing sales and quota carrying role&lt;/li&gt;
&lt;li&gt;3+ years of experience with public sector procurement in LATAM&lt;/li&gt;
&lt;li&gt;Experience selling SaaS based solutions&lt;/li&gt;
&lt;/ul&gt;
&lt;li&gt;Fluent English, Spanish &amp;amp; Portuguese required&lt;/li&gt;
&lt;li&gt;Able to travel up to 70%&lt;/li&gt;
&lt;li&gt;An extensive demonstrable track record in Software Sales (SaaS / Cloud)&lt;/li&gt;
&lt;li&gt;Relationship / consultative selling experience&lt;/li&gt;
&lt;li&gt;Able to clearly and directly articulate complex solution offerings&lt;/li&gt;
&lt;li&gt;Data management experience using Salesforce or similar CRM&lt;/li&gt;
&lt;li&gt;Virtualization and Cloud understanding&lt;/li&gt;
&lt;li&gt;Team Player - collaborate with various team members regularly&lt;/li&gt;
&lt;li&gt;Ready to own &amp;amp; drive the territory&lt;/li&gt;
&lt;li&gt;Startup experience &amp;amp; some vertical experience a plus&lt;/li&gt;
&lt;li&gt;Law Enforcement / Public Safety experience a plus&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Don’t meet every single requirement? That&#39;s ok. At Axon, we Aim Far. We think big with a long-term view because we want to reinvent the world to be a safer, better place. We are also committed to building diverse teams that reflect the communities we serve.&lt;/p&gt;
&lt;p&gt;Studies have shown that women and people of color are less likely to apply to jobs unless they check every box in the job description. If you’re excited about this role and our mission to Protect Life but your experience doesn’t align perfectly with every qualification listed here, we encourage you to apply anyways. You may be just the right candidate for this or other roles.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Important Notes&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;The above job description is not intended as, nor should it be construed as, exhaustive of all duties, responsibilities, skills, efforts, or working conditions associated with this job. The job description may change or be supplemented at any time in accordance with business needs and conditions.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Some roles may also require legal eligibility to work in a firearms environment.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We collect personal information from applicants to evaluate candidates for employment. You may request access, deletion, or exercise other CCPA rights at&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;mailto:axongreenhousesupport@axon.com&quot; target=&quot;_blank&quot; data-stringify-link=&quot;mailto:axongreenhousesupport@axon.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;axongreenhousesupport@axon.com&lt;/a&gt;&lt;/strong&gt;&amp;nbsp;or via our&amp;nbsp;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;https://privacyportal.onetrust.com/webform/0efc1702-9321-4119-bc9d-a06c3a1d3e4e/ca57cc26-a159-4193-9f6e-58ffe3fd2509&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://privacyportal.onetrust.com/webform/0efc1702-9321-4119-bc9d-a06c3a1d3e4e/ca57cc26-a159-4193-9f6e-58ffe3fd2509&quot; data-sk=&quot;tooltip_parent&quot;&gt;Axon Privacy Web Form&lt;/a&gt;. For more information, please see the Your California Privacy Rights section of our&amp;nbsp;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;https://www.axon.com/candidateprivacypolicy&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.axon.com/candidateprivacypolicy&quot; data-sk=&quot;tooltip_parent&quot;&gt;Applicant and Candidate Privacy Notice.&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Axon’s mission is to Protect Life and is committed to the well-being and safety of its employees as well as Axon’s impact on the environment. All Axon employees must be aware of and committed to the appropriate environmental, health, and safety regulations, policies, and procedures. Axon employees are empowered to report safety concerns as they arise and activities potentially impacting the environment.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are an equal opportunity employer that promotes justice, advances equity, values diversity and fosters inclusion. We’re committed to hiring the best talent — regardless of race, creed, color, ancestry, religion, sex (including pregnancy), national origin, sexual orientation, age, citizenship status, marital status, disability, gender identity, genetic information, veteran status, or any other characteristic protected by applicable laws, regulations and ordinances — and empowering all of our employees so they can do their best work. If you have a disability or special need that requires assistance or accommodation during the application or the recruiting process, please email &lt;a href=&quot;mailto:recruitingops@axon.com&quot;&gt;recruitingops@axon.com. &lt;/a&gt;&amp;nbsp;Please note that this email address is for accommodation purposes only. Axon will not respond to inquiries for other purposes.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;Phishing alert:&amp;nbsp; Axon will never ask you to pay for any part of the hiring process, including training, equipment, or background checks. We do not make job offers via text message, WhatsApp, or instant messaging platforms without a formal interview process.&amp;nbsp; All legitimate job openings are listed on our official careers page at &lt;a href=&quot;https://www.axon.com/careers&quot;&gt;https://www.axon.com/careers&lt;/a&gt;. &amp;nbsp;If you receive a suspicious offer or outreach from an email address that is not &lt;strong&gt;@axon.com&lt;/strong&gt;, or if you are asked for sensitive personal information (bank details, Social Security Number) prematurely, please ignore the message and report it to &lt;a href=&quot;mailto:recruitingops@axon.com&quot;&gt;recruitingops@axon.com&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

investedinthemission-axon:greenhouse:775.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h4&gt;&lt;strong&gt;Join Axon and be a Force for Good.&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;At Axon, we’re on a mission to Protect Life. We’re explorers, pursuing society’s most critical safety and justice issues with our ecosystem of devices and cloud software. Like our products, we work better together. We connect with candor and care, seeking out diverse perspectives from our customers, communities and each other.&lt;br&gt;&lt;br&gt;Life at Axon is fast-paced, challenging and meaningful. Here, you’ll take ownership and drive real change. Constantly grow as you work hard for a mission that matters at a company where you matter.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;&lt;strong&gt;Your Impact&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;&lt;br&gt;As Axon’s DC Operator I, you will play a key role in supporting accurate, safe, and efficient daily operations within our distribution center. This role helps ensure materials are received, moved, stored, picked, packed, and delivered on time to support Axon’s business and customer needs.&amp;nbsp;You’ll also serve as a resource for problem solving, training, and supporting new or less experienced team members, helping raise the standard for safety, quality, and operational execution across the team.&lt;br&gt;&lt;br&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;br&gt;Location: Onsite at our Phoenix, AZ office&lt;br&gt;Reports to: Senior Outbound Supervisor&lt;br&gt;Direct Reports: None&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Pick, pack, move, maintain, and store materials accurately and efficiently in accordance with distribution center procedures.&lt;/li&gt;
&lt;li&gt;Coordinate with other departments to support timely and accurate delivery of materials.&lt;/li&gt;
&lt;li&gt;Conduct detailed inventory checks, identify discrepancies, and report issues to ensure inventory accuracy.&lt;/li&gt;
&lt;li&gt;Use warehouse management systems, or WMS, on a computer or handheld scanner to perform daily job functions.&lt;/li&gt;
&lt;li&gt;Operate forklifts, pallet jacks, hand trucks, and other material handling equipment safely and effectively.&lt;/li&gt;
&lt;li&gt;Handle sensitive and hazardous materials according to safety and compliance requirements.&lt;/li&gt;
&lt;li&gt;Work cross-functionally across various warehouse departments to support daily operational priorities.&lt;/li&gt;
&lt;li&gt;Participate in team meetings, training sessions, and continuous improvement activities.&lt;/li&gt;
&lt;li&gt;Support new or less experienced team members by helping with training, troubleshooting, and day-to-day problem solving.&lt;/li&gt;
&lt;li&gt;Maintain a clean, organized, and safe work environment while demonstrating a positive and respectful attitude both independently and in a team setting.&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;&lt;strong&gt;What You Bring&lt;/strong&gt;&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;High school diploma, GED, or equivalent experience.&lt;/li&gt;
&lt;li&gt;Ability to read, write, and communicate in English.&lt;/li&gt;
&lt;li&gt;Experience working in a warehouse, distribution center, inventory, logistics, or materials handling environment.&lt;/li&gt;
&lt;li&gt;Forklift experience preferred; training may be provided onsite.&lt;/li&gt;
&lt;li&gt;Ability to safely lift and carry merchandise weighing up to50–75 lbsas required.&lt;/li&gt;
&lt;li&gt;Basic computer skills, including familiarity with Microsoft Word, Excel, warehouse management systems, handheld scanners, or similar tools.&lt;/li&gt;
&lt;li&gt;Strong attention to detail, reliability, and commitment to safety, accuracy, and operational excellence.&lt;/li&gt;
&lt;li&gt;A collaborative, respectful mindset with the ability to work independently and as part of a team.&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;&lt;br&gt;&lt;strong&gt;Work Location&lt;/strong&gt;&lt;br&gt;This role is based onsite at our Phoenix, AZ office. Due to the hands-on nature of distribution center operations, this role requires regular onsite presence to support material movement, inventory accuracy, equipment operation, and cross-functional warehouse coordination.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Benefits that Benefit You&lt;/strong&gt;&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Competitive salary and 401k with employer match&lt;/li&gt;
&lt;li&gt;Discretionary paid time off&lt;/li&gt;
&lt;li&gt;Paid parental leave for all&lt;/li&gt;
&lt;li&gt;Medical, Dental, Vision plans&lt;/li&gt;
&lt;li&gt;Fitness Programs&lt;/li&gt;
&lt;li&gt;Emotional &amp;amp; Mental Wellness support&lt;/li&gt;
&lt;li&gt;Learning &amp;amp; Development programs&lt;/li&gt;
&lt;li&gt;Employee Resource Groups, or ERGs&lt;/li&gt;
&lt;li&gt;And yes, we have snacks in our offices&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;&lt;em&gt;Benefits listed herein may vary depending on the nature of your employment and the location where you work.&lt;/em&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Don’t meet every single requirement? That&#39;s ok. At Axon, we Aim Far. We think big with a long-term view because we want to reinvent the world to be a safer, better place. We are also committed to building diverse teams that reflect the communities we serve.&lt;/p&gt;
&lt;p&gt;Studies have shown that women and people of color are less likely to apply to jobs unless they check every box in the job description. If you’re excited about this role and our mission to Protect Life but your experience doesn’t align perfectly with every qualification listed here, we encourage you to apply anyways. You may be just the right candidate for this or other roles.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Important Notes&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;The above job description is not intended as, nor should it be construed as, exhaustive of all duties, responsibilities, skills, efforts, or working conditions associated with this job. The job description may change or be supplemented at any time in accordance with business needs and conditions.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Some roles may also require legal eligibility to work in a firearms environment.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We collect personal information from applicants to evaluate candidates for employment. You may request access, deletion, or exercise other CCPA rights at&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;mailto:axongreenhousesupport@axon.com&quot; target=&quot;_blank&quot; data-stringify-link=&quot;mailto:axongreenhousesupport@axon.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;axongreenhousesupport@axon.com&lt;/a&gt;&lt;/strong&gt;&amp;nbsp;or via our&amp;nbsp;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;https://privacyportal.onetrust.com/webform/0efc1702-9321-4119-bc9d-a06c3a1d3e4e/ca57cc26-a159-4193-9f6e-58ffe3fd2509&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://privacyportal.onetrust.com/webform/0efc1702-9321-4119-bc9d-a06c3a1d3e4e/ca57cc26-a159-4193-9f6e-58ffe3fd2509&quot; data-sk=&quot;tooltip_parent&quot;&gt;Axon Privacy Web Form&lt;/a&gt;. For more information, please see the Your California Privacy Rights section of our&amp;nbsp;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;https://www.axon.com/candidateprivacypolicy&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.axon.com/candidateprivacypolicy&quot; data-sk=&quot;tooltip_parent&quot;&gt;Applicant and Candidate Privacy Notice.&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Axon’s mission is to Protect Life and is committed to the well-being and safety of its employees as well as Axon’s impact on the environment. All Axon employees must be aware of and committed to the appropriate environmental, health, and safety regulations, policies, and procedures. Axon employees are empowered to report safety concerns as they arise and activities potentially impacting the environment.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are an equal opportunity employer that promotes justice, advances equity, values diversity and fosters inclusion. We’re committed to hiring the best talent — regardless of race, creed, color, ancestry, religion, sex (including pregnancy), national origin, sexual orientation, age, citizenship status, marital status, disability, gender identity, genetic information, veteran status, or any other characteristic protected by applicable laws, regulations and ordinances — and empowering all of our employees so they can do their best work. If you have a disability or special need that requires assistance or accommodation during the application or the recruiting process, please email &lt;a href=&quot;mailto:recruitingops@axon.com&quot;&gt;recruitingops@axon.com. &lt;/a&gt;&amp;nbsp;Please note that this email address is for accommodation purposes only. Axon will not respond to inquiries for other purposes.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;Phishing alert:&amp;nbsp; Axon will never ask you to pay for any part of the hiring process, including training, equipment, or background checks. We do not make job offers via text message, WhatsApp, or instant messaging platforms without a formal interview process.&amp;nbsp; All legitimate job openings are listed on our official careers page at &lt;a href=&quot;https://www.axon.com/careers&quot;&gt;https://www.axon.com/careers&lt;/a&gt;. &amp;nbsp;If you receive a suspicious offer or outreach from an email address that is not &lt;strong&gt;@axon.com&lt;/strong&gt;, or if you are asked for sensitive personal information (bank details, Social Security Number) prematurely, please ignore the message and report it to &lt;a href=&quot;mailto:recruitingops@axon.com&quot;&gt;recruitingops@axon.com&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

ivp-taxbit:greenhouse:5986848004.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Company&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Founded by CPAs, tax attorneys, and engineers, Taxbit is the leading innovator automating global tax reporting for the digital economy. Taxbit&#39;s AI-enabled platform streamlines compliance related to digital assets, payments, and other financial transactions. Its unique combination of deep subject matter expertise and AI-forward technology have made it a fast-growing disruptor trusted by the world&#39;s leading fintechs, marketplaces, digital asset players, Big 4 accounting firms, traditional enterprises, and government agencies. Backed by top-tier Silicon Valley VCs, Taxbit&#39;s team is located across offices in San Francisco, New York, Seattle, Salt Lake City, London, Madrid, and Singapore.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Opportunity for Impact&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As an Implementation Manager, you’ll serve as a trusted advisor to our enterprise customers by:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partnering closely with exchanges, marketplaces, and FinTechs to design, implement, and activate TaxBit’s products and solutions&lt;/li&gt;
&lt;li&gt;Working in close collaboration with our engineers and subject matter experts (SMEs) to optimize quality and business impact for your portfolio of customers&lt;/li&gt;
&lt;li&gt;Creating feedback loops from our largest customers back to our engineering teams to help inform our product roadmap and design value-adding products&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You’ll have lots of fun opportunities to scale your impact in a hypergrowth startup!&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Role and Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Project manage complex implementation engagements for enterprise accounts&lt;/li&gt;
&lt;li&gt;Oversee overall project plan and implementation with TaxBit SMEs and engineers&lt;/li&gt;
&lt;li&gt;Capture and document clients’ business goals then translate the goals into technical requirements&lt;/li&gt;
&lt;li&gt;Work with TaxBit SMEs and engineers to document clients’ data requirements and architecture to drive discussions with clients&lt;/li&gt;
&lt;li&gt;Establish, develop and own client relationships with business and IT stakeholders&lt;/li&gt;
&lt;li&gt;Help clients integrate with TaxBit’s product suite&lt;/li&gt;
&lt;li&gt;Debug and investigate complex issues independently and escalate as needed&lt;/li&gt;
&lt;li&gt;Lead customer launches and ensure post go-live success&lt;/li&gt;
&lt;li&gt;Contribute to a great team culture and working environment&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Professional Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Bachelor’s Degree in Accounting, Business, Information Systems or similar&lt;/li&gt;
&lt;li&gt;4+ years of experience in technology consulting, professional services, data analysis or related fields&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Personal Characteristics&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Fluent in English; native fluency in a main European language; preferred business-level proficiency in 1-2 additional languages&lt;/li&gt;
&lt;li&gt;Experience in enterprise architecture, including AWS, integration technologies, and APIs&lt;/li&gt;
&lt;li&gt;Experience working with Engineering teams&lt;/li&gt;
&lt;li&gt;Effective communication and client management skills&lt;/li&gt;
&lt;li&gt;Strong problem solving skills and an ability to thrive amidst ambiguity&lt;/li&gt;
&lt;li&gt;Strong desire to work in a hyper-growth startup with a collaborative teamwork and leadership approach&lt;/li&gt;
&lt;li&gt;Passion for and curiosity about digital assets&lt;/li&gt;
&lt;li&gt;Background and expertise in FinTech, RegTech, or Tax &amp;amp; Accounting preferred&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The base salary range for this role is €60,000–€100,000. Certain roles may be eligible for incentive compensation, equity, and benefits. Actual compensation will vary depending on various job-related factors, including, but not limited to location, experience, level, and job qualifications.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Benefits &amp;amp; Perks&lt;/strong&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Competitive cash compensation (based on experience)&lt;/li&gt;
&lt;li&gt;Equity (RSUs)&lt;/li&gt;
&lt;li&gt;Competitive benefits package&lt;/li&gt;
&lt;li&gt;Modern pension plan&lt;/li&gt;
&lt;li&gt;Financial wellness benefits&lt;/li&gt;
&lt;li&gt;Hybrid work model: 3 days in-office, 2 days remote/flexible&lt;/li&gt;
&lt;li&gt;Paid Time Off (PTO)&lt;/li&gt;
&lt;li&gt;Monday team lunches, snacks, and drinks&lt;/li&gt;
&lt;li&gt;Paid parental leave&lt;/li&gt;
&lt;li&gt;Workplace autonomy and flexibility in task execution&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;p&gt;&lt;strong&gt;Empresa&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Fundada por contables públicos (CPA), abogados fiscalistas e ingenieros, Taxbit es la empresa líder en innovación dedicada a automatizar la información fiscal global para la economía digital. La plataforma de Taxbit, impulsada por inteligencia artificial, agiliza el cumplimiento normativo relacionado con activos digitales, pagos y otras transacciones financieras. Su combinación única de profundo conocimiento especializado y tecnología avanzada de IA la han convertido en una entidad disruptiva de rápido crecimiento, en la que confían las principales empresas &lt;em&gt;fintech&lt;/em&gt;, &lt;em&gt;marketplaces&lt;/em&gt; y actores del sector de activos digitales del mundo, así como las &quot;Big 4&quot;, empresas tradicionales y agencias gubernamentales. Respaldada por fondos de capital riesgo de primer nivel de Silicon Valley, el equipo de Taxbit trabaja desde sus oficinas en San Francisco, Nueva York, Seattle, Salt Lake City, Londres, Madrid y Singapur.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Oportunidad de impacto&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Como &lt;strong&gt;Implementation Manager&lt;/strong&gt; (gestor/a de implantación), actuarás como asesor de confianza para nuestros clientes corporativos mediante las siguientes funciones:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Colaborar estrechamente con plataformas de intercambio (&lt;em&gt;exchanges&lt;/em&gt;), empresas &lt;em&gt;FinTech, &lt;/em&gt;y &lt;em&gt;Marketplaces&lt;/em&gt; para diseñar, implementar y poner en marcha los productos y soluciones de Taxbit&lt;/li&gt;
&lt;li&gt;Trabajar en colaboración directa con nuestros ingenieros y expertos en la materia (SMEs) para optimizar la calidad y el impacto de negocio en tu cartera de clientes&lt;/li&gt;
&lt;li&gt;Crear canales de retroalimentación (&lt;em&gt;feedback loops&lt;/em&gt;) entre nuestros clientes más importantes y nuestros equipos de ingeniería, ayudando a definir nuestra hoja de ruta (&lt;em&gt;roadmap&lt;/em&gt;) y a diseñar productos que aporten valor añadido.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;¡Tendrás varias oportunidades para ampliar tu impacto en una &lt;em&gt;startup&lt;/em&gt; en fase de hipercrecimiento!&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Funciones y responsabilidades&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Gestionar proyectos de implantación complejos para cuentas corporativas (&lt;em&gt;enterprise&lt;/em&gt;)&lt;/li&gt;
&lt;li&gt;Supervisar el plan de proyecto global y su ejecución junto con los ingenieros y expertos en la materia (SMEs) de Taxbit&lt;/li&gt;
&lt;li&gt;Captar y documentar los objetivos de negocio de los clientes para, posteriormente, traducirlos en requisitos técnicos&lt;/li&gt;
&lt;li&gt;Colaborar con los ingenieros y expertos de Taxbit en la documentación de la arquitectura y los requisitos de datos de los clientes para liderar las reuniones técnicas&lt;/li&gt;
&lt;li&gt;Establecer, desarrollar y consolidar relaciones sólidas con los interlocutores de negocio y de TI (&lt;em&gt;stakeholders&lt;/em&gt;) del cliente&lt;/li&gt;
&lt;li&gt;Ayudar a los clientes en la integración con el ecosistema de productos de Taxbit&lt;/li&gt;
&lt;li&gt;Investigar y resolver incidencias complejas de forma autónoma, realizando el escalado de las mismas cuando sea necesario&lt;/li&gt;
&lt;li&gt;Liderar los lanzamientos de los clientes y asegurar el éxito del proyecto tras la puesta en marcha (&lt;em&gt;go-live&lt;/em&gt;)&lt;/li&gt;
&lt;li&gt;Contribuir a mantener una excelente cultura de equipo y un gran ambiente de trabajo&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Perfil profesional&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Titulación universitaria en Contabilidad, Administración de Empresas, Sistemas de Información o una disciplina similar&lt;/li&gt;
&lt;li&gt;Más de 4 años de experiencia en consultoría tecnológica, servicios profesionales, análisis de datos o campos relacionados&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Aptitudes personales&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Fluidez de inglés; fluidez nativa en un idioma europeo principal; se valorará positivamente un nivel profesional en 1 o 2 idiomas adicionales&lt;/li&gt;
&lt;li&gt;Experiencia en arquitectura corporativa, incluyendo AWS, tecnologías de integración y APIs&lt;/li&gt;
&lt;li&gt;Experiencia colaborando con equipos de ingeniería&lt;/li&gt;
&lt;li&gt;Excelentes habilidades de comunicación y gestión de clientes&lt;/li&gt;
&lt;li&gt;Gran capacidad de resolución de problemas y habilidad para prosperar en entornos ambiguos&lt;/li&gt;
&lt;li&gt;Fuerte deseo de trabajar en una &lt;em&gt;startup&lt;/em&gt; en fase de hipercrecimiento, con un enfoque basado en el liderazgo y el trabajo en equipo colaborativo&lt;/li&gt;
&lt;li&gt;Pasión y curiosidad por el sector de los activos digitales&lt;/li&gt;
&lt;li&gt;Se valorará positivamente contar con formación o experiencia previa en &lt;em&gt;FinTech&lt;/em&gt; o en el ámbito fiscal y contable&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Remuneración&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;El rango de salario base para este puesto es de €60,000–€100,000. Algunos puestos pueden optar a una remuneración variable, acciones de la empresa y beneficios. La compensación final variará en función de diversos factores relacionados con el puesto, incluyendo, entre otros: la ubicación, la experiencia, el nivel y las cualificaciones profesionales.&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Beneficios y ventajas&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Remuneración monetaria competitiva (según experiencia)&lt;/li&gt;
&lt;li&gt;Acciones de la empresa (RSU)&lt;/li&gt;
&lt;li&gt;Paquete de beneficios competitivo&lt;/li&gt;
&lt;li&gt;Plan de pensiones moderno&lt;/li&gt;
&lt;li&gt;Beneficios de bienestar financiero&lt;/li&gt;
&lt;li&gt;Modelo de trabajo híbrido: 3 días en la oficina, 2 días de teletrabajo/flexible&lt;/li&gt;
&lt;li&gt;Permiso retribuido&lt;/li&gt;
&lt;li&gt;Almuerzos de equipo los lunes, aperitivos y bebidas&lt;/li&gt;
&lt;li&gt;Baja por maternidad/paternidad remunerada para el cuidado de su hijo&lt;/li&gt;
&lt;li&gt;Autonomía laboral y flexibilidad en la ejecución del trabajo.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Taxbit in the News&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&quot;https://www.prnewswire.com/news-releases/bybit-collaborates-with-taxbit-to-ensure-seamless-financial-compliance-for-global-and-eu-users-302610053.html&quot; target=&quot;_blank&quot;&gt;Bybit Collaborates with Taxbit to Ensure Seamless Financial Compliance for Global and EU Users&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.prnewswire.com/news-releases/taxbit-expands-global-platform-to-power-carfdac8-compliance-at-scale-302411671.html&quot; target=&quot;_blank&quot;&gt;Taxbit Expands Global Platform to Power CARF/DAC8 Compliance at Scale&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.prnewswire.com/news-releases/taxbit-unveils-industry-first-global-reporting-platform-bridging-digital-and-traditional-finance-302304125.html&quot; target=&quot;_blank&quot;&gt;Taxbit Unveils Industry-First Global Reporting Platform, Bridging Digital and Traditional Finance&lt;/a&gt;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.prnewswire.com/news-releases/taxbit-named-to-2024-deloitte-technology-fast-500-list-of-fastest-growing-companies-in-north-america-302313123.html&quot; target=&quot;_blank&quot;&gt;Taxbit Wins the Digital Banker’s 2025 Digital Assets Award for Best Technology Solution Provider for Digital Assets - Tax &amp;amp; Compliance Automation&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.prnewswire.com/news-releases/taxbit-named-to-2024-deloitte-technology-fast-500-list-of-fastest-growing-companies-in-north-america-302313123.html&quot; target=&quot;_blank&quot;&gt;Taxbit Named to 2024 Deloitte Technology Fast 500™ List of Fastest-Growing Companies in North America&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://ffnews.com/newsarticle/paytech/taxbit-appoints-former-oecd-advisor-colby-mangels-as-global-head-of-government-solutions/&quot; target=&quot;_blank&quot;&gt;Taxbit Appoints Former OECD Advisor Colby Mangels as Global Head of Government Solutions&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;https://www.taxbit.com/webinars/unlocking-compliance-at-scale-carf-dac8-reporting-for-digital-asset-platforms/&quot; target=&quot;_blank&quot;&gt;Unlocking Compliance at Scale: CARF/DAC8 Reporting for Digital Asset Platforms&lt;/a&gt;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Disclaimers&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;By submitting an application for this role, you certify that the information contained in the application is correct to the best of your knowledge. You understand that to falsify information is&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;grounds for refusing to hire you, or for discharge should you be hired.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;For US roles, employment with the Company is at will unless otherwise stated in a written agreement signed by the CEO of the Company.&amp;nbsp; This means that either the Company or the employee can terminate the employment at any time and for any reason, with or without notice.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

launchtn-pilot-3-208c6413-9fd2-4901-97c9.descriptionHtml:
&lt;h2&gt;&lt;strong&gt;The Role&lt;/strong&gt;&lt;/h2&gt;
&lt;div&gt;
&lt;p&gt;Most lifecycle marketers manage email programs. This one owns a pipeline.&lt;/p&gt;
&lt;p&gt;You&#39;ll be the senior IC responsible for lifecycle-influenced pipeline, expansion revenue from existing customers, and conversion efficiency across the full funnel—from trial activation through to post-sales growth. The motion works. Your job is to make it compound.&lt;/p&gt;
&lt;p&gt;This isn&#39;t an execution-only role. You&#39;ll decide which behavioral and product usage signals matter, partner with our Data team to turn propensity models into actionable segments, and build the programs that move accounts through the funnel and into expansion. You&#39;ll work closely with Sales, our Consulting services team, Growth Marketing, and RevOps to make those plays land.&lt;/p&gt;
&lt;p&gt;You&#39;ll report to the VP of Marketing and operate as a senior individual contributor. There are no direct reports, but you&#39;ll work with a team of senior specialists across growth marketing, marketing ops, content, growth engineering, and product marketing, giving you the infrastructure to build full-funnel programs without building a team from scratch.&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;h2&gt;&lt;span class=&quot;ace-all-bold-hthree&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz82z5cz80zrcsicz79ziz74zqz66zcmw52h9z67zl9jmz88zwz67zz86zr&quot;&gt;&lt;strong&gt;What You&#39;ll Own&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Lifecycle pipeline.&lt;/strong&gt; You own the programs that turn leads into SQLs through lifecycle—industry nurtures, referral programs, intent-based routing, and partnership channel conversion.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Expansion revenue.&lt;/strong&gt; Working with product usage signals and propensity model outputs, you&#39;ll identify expansion-ready accounts and activate lifecycle and account management plays for high-propensity tiers.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Conversion efficiency.&lt;/strong&gt; From trial activation and onboarding through early retention—activation rate and early churn are your metrics. You also own Lead → SQL conversion through lifecycle personalization and segmentation.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Experimentation.&lt;/strong&gt; Structured tests with documented hypotheses and results. Not just subject lines—program logic, timing, audience strategy, and channel mix.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Champion AI and automation. &lt;/strong&gt;Identify and use AI-powered tools to automatically detect friction points and hidden customer segments. Employ generative AI and dynamic content blocks to tailor messaging and educational assets per customer profile.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Develop customer education strategies.&lt;/strong&gt; In partnership with product, operations, and marketing teams to help prospects and customers fully realize the value of Pilot’s solutions.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&amp;nbsp;&lt;strong&gt;What Success Looks Like in Year 1&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Full program audit completed and quick wins shipped in the first 30 days&lt;/li&gt;
&lt;li&gt;Lifecycle-influenced Lead → SQL conversion measurably up&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Expansion plays live, running off propensity tiers, and attributed pipeline increasing QoQ&lt;/li&gt;
&lt;li&gt;A structured experimentation cadence with documented learnings rolling forward&lt;/li&gt;
&lt;li&gt;Weekly lifecycle reporting live and owned—you&#39;re the person who knows what&#39;s working and why&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;span class=&quot;ace-all-bold-hthree&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qowz82z5cz80zrcsicz79ziz74zqz66zcmw52h9z67zl9jmz88zwz67zz86zr&quot;&gt;&lt;strong&gt;About You&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;You&#39;ve owned lifecycle programs that are accountable to pipeline and revenue, not just engagement metrics. You know your way around an enterprise MAP at an architectural level, and you&#39;re as comfortable building complex triggered flows as you are making a strategic call about which segment to test next.&lt;/p&gt;
&lt;p&gt;You&#39;re a strong enough writer to own lifecycle copy without leaning on a content team for every send. You can read cohort data and act on it, but you partner with data specialists on the modeling rather than building it yourself.&lt;/p&gt;
&lt;p&gt;More specifically:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;7+ years of experience in lifecycle marketing, customer marketing, or customer engagement roles, ideally within a B2B SaaS or high-growth environment&lt;/li&gt;
&lt;li&gt;Significant experience in Marketo. You build programs from scratch, not from templates&lt;/li&gt;
&lt;li&gt;A track record of owning pipeline or revenue metrics&lt;/li&gt;
&lt;li&gt;Proven track record of designing and executing successful lifecycle programs across multiple customer segments&lt;/li&gt;
&lt;li&gt;A structured approach to experimentation with clear hypotheses, meaningful tests, learnings that roll forward&lt;/li&gt;
&lt;li&gt;Skilled at analyzing customer data with the ability to translate cohort and funnel data into program decisions&lt;/li&gt;
&lt;li&gt;Hands-on experience collaborating with cross-functional stakeholders (product, engineering, customer success, sales)&lt;/li&gt;
&lt;li&gt;Working knowledge of Salesforce data models&lt;/li&gt;
&lt;li&gt;Solid deliverability and compliance fundamentals (SPF/DKIM, list hygiene, CAN-SPAM, CCPA)&lt;/li&gt;
&lt;li&gt;Comfortable navigating a fast-paced, startup environment&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Nice to have:&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;MAP certification (MCE or equivalent)&lt;/li&gt;
&lt;li&gt;B2B SaaS background, fintech or accounting-adjacent is a bonus&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;What We&#39;re Not Looking For&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Someone who needs to build statistical models from scratch. We have a data team for that. What we need is someone who understands what a propensity model is telling them and knows exactly what to build next.&lt;/p&gt;
&lt;h2&gt;About Pilot&lt;/h2&gt;
&lt;p&gt;Pilot launched in 2017 to bring the back office into the modern era. Pilot provides small businesses with dedicated finance experts - which Pilot hires as full-time, U.S.-based employees - who learn the ins-and-outs of their business. Pilot integrates directly with the billing, banking, expense, and payroll systems customers already use. With a special blend of custom software and expert bookkeepers, Pilot delivers accurate, consistent bookkeeping and financial management and tax services that give entrepreneurs the freedom to focus on their business.&lt;/p&gt;
&lt;p&gt;Pilot has over 3,000 customers and has raised over $170 million in financing from Sequoia, Index Ventures, Stripe, Bezos Expeditions, and Whale Rock.&amp;nbsp; Our investors also include a long list of world-class entrepreneurs, including Patrick and John Collison, Drew Houston, and Diane Greene.&amp;nbsp; Our most recent funding round doubled our valuation to $1.2 billion – &lt;a href=&quot;https://pilot.com/blog/pilot-unicorn-bezos-expeditions-whale-rock/&quot;&gt;Meet Fintech’s Newest Unicorn&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;The marketing team has grown 3x in the past year. It’s a group of channel experts—demand gen, lifecycle, paid, product marketing, partner marketing, content, and ops—who operate with high ownership and drive a significant share of Pilot’s revenue. The team is collaborative, moves quickly, and takes its craft seriously.&lt;/p&gt;
&lt;h2&gt;Why Pilot?&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;We invest in our employees’ development and happiness because our employees are the keys to our success and ensuring happy customers&lt;/li&gt;
&lt;li&gt;The opportunity to join a seasoned founding team that has led companies through two prior successful startups and acquisitions (by Oracle and Dropbox).&lt;/li&gt;
&lt;li&gt;Flexible vacation/time-off policy&lt;/li&gt;
&lt;li&gt;All federal holidays are observed&lt;/li&gt;
&lt;li&gt;Competitive benefits package including additional wellness benefits&lt;/li&gt;
&lt;li&gt;Parental leave for birthing or non-birthing parents – 100% pay for 12 weeks&lt;/li&gt;
&lt;li&gt;401(k) plan&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;&lt;span class=&quot; author-d-1gg9uz65z1iz85zgdz68zmqkz84zo2qotvojz75zcn0z80zc9wz75z9ynz68zz79zhez77z8z71zonz66zz84zz67zwv7n&quot;&gt;The base pay range target for the role seniority described in this job description is $127K - $215K in most remote locations, and between $159K - $215K in San Francisco, CA and New York City, NY. Final offer amounts depend on multiple factors such as candidate experience and expertise, geographic location, total compensation, and market data. In addition to cash pay, full-time regular positions are eligible for equity, 401(k), health benefits, and other benefits; some of these benefits may be available for part-time or temporary positions.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Pilot commits to provide a work environment free of discrimination and harassment, as well as equal employment opportunity regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability, gender identity or Veteran status. We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. You may view all of Pilot’s &lt;a href=&quot;https://pilot.com/recruiting-notices&quot;&gt;recruiting notices here&lt;/a&gt;, including our EEO policy, information about requesting a reasonable accommodation in the job application process, recruitment agency policy, recruitment scam notice, and important E-Verify information. You may view our job candidate privacy policy &lt;a href=&quot;https://pilot.com/terms/privacy-job-candidate&quot;&gt;here&lt;/a&gt;.&lt;/p&gt;
&lt;/div&gt;

leadershipforeducationalequity-aviation-.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Training Tomorrow&#39;s Technicians to Become Skilled, Employable and Essential. &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Us  - Big Changes, Better Benefits - Join us today!&amp;nbsp;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The&lt;strong&gt;&amp;nbsp;Aviation Institute of Maintenance (AIM)&lt;/strong&gt;,&amp;nbsp;established&amp;nbsp;in 1969, is a premier institution dedicated to advancing the field of aviation maintenance through exceptional education and training. With 15 campuses nationwide, AIM is a cornerstone in the aviation industry, accounting for 20% of all students attending FAA-certified Airframe &amp;amp; Powerplant (A&amp;amp;P) schools across the country. Each year, AIM proudly contributes to the graduation of&amp;nbsp;nearly one&amp;nbsp;in four certified&amp;nbsp;aircraft&amp;nbsp;technicians in America.&lt;/p&gt;
&lt;p&gt;At AIM, you&#39;ll become part of a dynamic team of educators and leaders, all united by a shared commitment to delivering top-notch training and ensuring student success. We are passionate about equipping the next generation of aircraft technicians with the skills and knowledge needed to excel in the aviation industry. If you are eager to make a meaningful impact and help shape the future of aviation maintenance, AIM offers a rewarding environment where your contributions will truly matter.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(35, 111, 161);&quot;&gt;&lt;strong&gt;Location: 329 E Little Creek Rd&amp;nbsp;Norfolk, VA 23518&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt; color: rgb(35, 111, 161);&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Compensation: Up to $36 per hour&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Are you an A&amp;amp;P Mechanic ready for a new chapter in your aviation career?&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The Aviation Institute of Maintenance (AIM)—the largest aviation maintenance training school in the U.S.—is seeking experienced Aircraft Maintenance Technicians (AMTs),&amp;nbsp;Aircraft&amp;nbsp;Mechanics, and FAA-certified A&amp;amp;P Mechanics to join our team as instructors.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If you have hands-on experience in&amp;nbsp;aircraft&amp;nbsp;maintenance and enjoy mentoring others, this is your opportunity to step out of the hangar and into a role where you can shape the next generation of aviation professionals.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This opportunity is ideal for professionals exploring aviation mechanic jobs,&amp;nbsp;aircraft&amp;nbsp;maintenance careers, or instructor roles in aviation training.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;No prior teaching experience&amp;nbsp;required.&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;We provide a&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;5-day paid instructor training program&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to help you successfully transition into the classroom.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Why Consider Teaching?&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Many skilled A&amp;amp;P mechanics and aviation technicians&amp;nbsp;don’t&amp;nbsp;initially consider teaching—but those who do often find it to be one of the most rewarding paths in their career.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At AIM,&amp;nbsp;you’ll:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Share your real-world aircraft maintenance experience with future technicians&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Enjoy more predictable schedules compared to field work&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Make a lasting impact on students entering the aviation industry&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Continue growing your own knowledge while developing others&amp;nbsp;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the Role&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW53309533 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;As&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;an Aircraft&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;&amp;nbsp;Maintenance Instructor (A&amp;amp;P Mechanic Instructor), you will deliver&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW53309533 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;FAA Part 147-aligned&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW53309533 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;&amp;nbsp;aviation maintenance curriculum and provide hands-on instruction to students&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun ContextualSpellingAndGrammarErrorV2Themed SCXW53309533 BCX0&quot;&gt;preparing for&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;&amp;nbsp;careers as&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;aircraft&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW53309533 BCX0&quot;&gt;&amp;nbsp;maintenance technicians (AMTs).&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW53309533 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW37426895 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW37426895 BCX0&quot;&gt;This role is ideal for experienced A&amp;amp;P mechanics,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW37426895 BCX0&quot;&gt;aircraft&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW37426895 BCX0&quot;&gt;&amp;nbsp;mechanics, and aviation maintenance professionals who want to combine technical&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW37426895 BCX0&quot;&gt;expertise&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW37426895 BCX0&quot;&gt;&amp;nbsp;with mentorship and training while delivering hands-on aviation maintenance instruction in classroom and active hangar environments.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW37426895 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Schedule Options&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Option 1 (Days): Monday - Thursday 7am-3:30pm &lt;strong&gt;OR&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Option 2 (Nights): Monday - Thursday 3pm-11:30pm&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Key Responsibilities&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
